    require write_tx(luwkw, kw) & (~abort_tx(luwkw)) & (write_tx(T, kw) -> (le(T, luwkw) | abort_tx(T)));
    require exists HT. depends_tx(lurkw, kw, HT) & (~abort_tx(lurkw)) & (read_tx(T, kw) -> le(T, lurkw) | abort_tx(T));

