	    write_tx(TX1, K) & # TX1 wrote K
	    depends_tx(TX2, K, T3) & # TX2 read K
	    ~le(TX1, T3)))
        & ((commit_tx(T) & op_in_tx(T, O) & op_node(O, N)) -> precommit_tx(T, N))   # Safety: Atomicity

invariant commit_tx(TX1) & commit_tx(TX2) & le(TX1, TX2) & write_tx(TX1, K) & depends_tx(TX2, K, T3) -> le(TX1, T3)
invariant commit_tx(T) & op_in_tx(T, O) & op_node(O, N) -> precommit_tx(T, N)
invariant commit_tx(TX) & write_tx(TX, K) & commit_tx(TX2) & depends_tx(TX2, K, T3) & le(T3, TX) & le(TX, TX2) -> TX = T3

