# The safety property is given by the invariants of the
# acyclic_partial_function module, that state that the routing tables
# do not create cycles.

invariant [safety_1000000] route_tc(N, X, X) & (route_tc(N, X, Y) & route_tc(N, Y, Z) -> route_tc(N, X, Z)) & (route_tc(N, X, Y) & route_tc(N, Y, X) -> X = Y) & (route_tc(N, X, Y) & route_tc(N, X, Z) -> (route_tc(N, Y, Z) | route_tc(N, Z, Y)))

invariant route_tc(N, X, Y) & X ~= Y -> route_dom(N, X)

