invariant [safety_mutex] pc3(T1) & pc3(T2) -> T1 = T2

invariant [uniq] forall T1:thread, T2:thread, K:ticket. m(T1,K) & m(T2,K) & T1 ~= T2 -> K = zero
invariant [pc2_ge_service] forall T:thread, K:ticket. pc2(T) & m(T,K) -> le(service, K)
invariant [pc3_eq_service] forall T:thread, K:ticket. pc3(T) & m(T,K) -> K = service
invariant [ticket_le_next] forall T:thread, K:ticket. m(T,K) & K ~= zero -> le(K, next_ticket)
invariant [service_le_next] le(service, next_ticket)
invariant [pc3_lt_next] forall T:thread. pc3(T) -> service ~= next_ticket
invariant [pc3_has_ticket] forall T:thread. pc3(T) -> m(T, service)

