# safety property:
invariant [safety_1] (    decision(N1,R1,V1) &
    decision(N2,R2,V2)
) -> V1 = V2

invariant forall N1:node, N2:node, R:round, V1:value, V2:value. vote(N1,R,V1) & vote(N2,R,V2) -> V1 = V2
invariant forall R:round, V1:value, V2:value. proposal(R,V1) & proposal(R,V2) -> V1 = V2
invariant forall R:round, V1:value, V2:value. chosenAt(R,V1) & chosenAt(R,V2) -> V1 = V2
invariant forall R1:round, R2:round, V1:value, V2:value. le(R1,R2) & chosenAt(R1,V1) & chosenAt(R2,V2) -> V1 = V2
invariant forall R:round, V:value, R1:round, V1:value. isSafeAtPaxos(R,V) & chosenAt(R1,V1) & le(R1,R) -> V = V1
invariant forall N:node, R:round, RMAX:round, V:value. one_b_max_vote(N,R,RMAX,V) & RMAX ~= negone -> vote(N,RMAX,V)
invariant forall N:node, R:round, RMAX:round, V:value, R2:round, V2:value. one_b_max_vote(N,R,RMAX,V) & vote(N,R2,V2) & le(R2,R) -> le(R2,RMAX)
invariant forall N:node, R:round, RMAX:round, V:value. one_b_max_vote(N,R,RMAX,V) -> le(RMAX,R) & RMAX ~= R
invariant forall N:node, R:round, V:value. one_b_max_vote(N,R,negone,V) -> forall R2:round, V2:value. ~(vote(N,R2,V2) & le(R2,R))

